INSERT INTO public.library_manager_ai_knowledge(slug,title,answer,keywords,sort_order) VALUES
('overview','What Library Manager does','Library Manager manages physical library copies, scanning and Review intake, inventory, lending and returns, overdue notices, Book of the Week and the reading guide. Administrators manage the collection while standard library users have lending and returning permissions.',ARRAY['app','overview','features','library'],1),
('sign-in','Sign in to Library Manager','Sign in with an existing Library Manager membership account. Supabase role validation decides whether you have administrator or library-user access. Accounts in other apps using this same Supabase project do not automatically grant library membership.',ARRAY['login','signin','account','credentials'],2),
('user-roles','Library Manager administrator versus library user','Administrators can manage inventory, scan and review books, notifications, contact details and featured books. Library users handle Lend and Return. Administrator access must be granted through the approved invitation or private access-code process.',ARRAY['admin','user','role','permission'],3),
('scan-books','Scan books','Open Scan books, upload clear book-cover photos using Choose photos, folder or ZIP, and start the scan. OCR runs on-device. Review suggested metadata carefully before saving because scanning and external lookup may be inaccurate.',ARRAY['scan','ocr','upload','camera','photos'],8),
('review-books','Review scanned books','Open Review books to inspect and correct OCR suggestions. Set valid title, author, ISBN/barcode, cover and shelf details; Save selected writes new physical copies to Supabase, while Update corrects existing copies. Unfinished Review work is synchronized through Supabase.',ARRAY['review','edit','save','queue'],10),
('scan-duplicates','Why exact duplicate photos are skipped','The scan pipeline computes an SHA-256 digest of original photo bytes and checks a shared Supabase registry to avoid uploading the exact same image again from folders, ZIPs or another device. Different photographs can have different hashes. Several physical books may legitimately share an ISBN.',ARRAY['duplicate','scan','photo','upload'],9),
('inventory','Use Inventory','Administrators can search books by title, author, ISBN or shelf; apply filters, choose grid/table layouts and update book details. Individual physical copies are tracked by unique Book IDs even when they have identical ISBN values.',ARRAY['inventory','books','shelf','filter','copies'],12),
('lend-book','Lend a library book','Use Lend a book to find an available physical copy, confirm the Book ID, enter borrower and due-date details, and submit. The loan is saved in Supabase and the copy becomes unavailable until returned.',ARRAY['lend','borrow','due','checkout'],15),
('return-book','Return a library book','Use Return a book to select an active loan and confirm the specific borrowed copy. Submitting marks the loan returned in Supabase and restores that physical copy to available inventory.',ARRAY['return','checkin','borrowed'],16),
('overdue','Overdue notifications','Library Manager derives overdue reminders from active loan records and due dates. Administrators can review overdue notifications and loan history. Do not put borrower details into the AI chat.',ARRAY['overdue','notification','reminders','due'],17),
('book-of-week','Book of the Week','The weekly spotlight features a verified library title with a reading reason and bibliographic details. The public page and reading guide exclude private borrower records. Administrators can manage the selected featured title.',ARRAY['weekly','featured','spotlight','book'],20),
('reading-guide','Use the reading guide','From Book of the Week open Read the full book guide. See verified title and author details, available synopsis, reading value, target audience and discussion ideas. External catalogue descriptions should only be used after matching the title or edition.',ARRAY['reading','guide','synopsis','discussion'],21),
('ai-assistant','Use Library AI','The floating Library AI provides app navigation guidance using a dedicated Supabase app-knowledge table and can answer general questions through server-configured AI models. Selected book details are optional context. It cannot access borrower records or change the database for you.',ARRAY['assistant','ai','app','help'],22),
('ai-chat-memory','Supabase AI conversation storage','Library AI conversations and messages are stored privately in Supabase for each signed-in library member and restored on another device. No AI chat history is stored in browser localStorage or sessionStorage. If cloud persistence fails the app must not claim the reply was saved.',ARRAY['cloud','chat','history','storage','sync'],23),
('reset-ai-chat','Reset the cloud AI conversation','Open the floating Library AI panel, press Reset at the top, and confirm. Reset deletes your current conversation and its messages from Supabase on every device without affecting books, loans, scanner review work or other members.',ARRAY['reset','clear','delete','conversation'],24),
('web-research','Optional web research','Use Chat options > Search the web when you need recent information. Provider support for web grounding varies. If it is unavailable, explain that current claims are unverified rather than pretending to have searched online.',ARRAY['web','search','research','current'],25),
('privacy','Library AI privacy','AI chat is restricted to signed-in Library Manager members and its database rows have user-specific Row Level Security. Do not share passwords, administrator codes, API keys, personal borrower data or private loan records with the assistant.',ARRAY['privacy','security','password','borrower'],27),
('sync','Refresh the shared collection','Inventory, loans and Review-queue records are backed by Supabase. Use Refresh from cloud to check changes made by other authorized devices. Camera OCR and some display preferences remain local device operations.',ARRAY['refresh','sync','supabase','review'],28),
('daily-usage-user','Daily library check in, books read and check out','Open the Check in / out page from the library user navigation. Enter your name, choose your purpose and press Check in. Only this action registers an attendance visit. Add titles actually read and press Save books, then Check out to finish the visit. Supabase supplies the actual arrival and departure timestamps, displayed as West Africa Time. Signing into the website alone is not an attendance check-in.',ARRAY['daily','visit','check','in','out','attendance','books','reading','log'],31),
('daily-usage-admin','Administrator daily usage register','Administrators open Monitor & Reports > Daily usage log. The list contains only library members who explicitly checked in. It shows verified account email, visitor name, arrival date and time, check-out date and time, duration, titles read, reason and visit notes. Filter by dates, status, name, email or book title; expand any row for details and export the filtered register to CSV. Unchecked-in registered accounts never appear.',ARRAY['admin','attendance','log','daily','dashboard','export','visitors'],32),
('daily-usage-privacy','Daily attendance and security','Daily visit records are stored in Supabase behind Row Level Security. Regular library users read only their own visits. Administrators can read the complete usage report. Database functions record times and prevent date or checkout tampering. Existing records may remain open if a member forgets to check out; an open visit is not proof the person is physically still in the library.',ARRAY['privacy','daily','attendance','time','security','checkout'],33)
